// Physical nexus established - filing required
// Apportionment will be calculated by tables 7000-7500
"GA filing required: Physical presence (office, employees, or property in state). Reference: GA Code § 48-7-21, § 48-7-31" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
// Apportionment will be calculated by tables 7000-7500
"GA filing required: Economic nexus (post-Wayfair). Threshold: $100,000 gross receipts OR 200 transactions. Reference: GA Code § 48-8-2(8)(K)" job.audit_trail swap addto

// Calculate Georgia state additions
0.0 /additions xdef

// Add back federal interest (tax-exempt federally but taxable to GA)
// additions revenue.federal_bond_interest add /additions xdef

// Add back IRC 199A deduction if state doesn't conform
// additions result.section_199a_deduction add /additions xdef

// Add back state income taxes deducted federally
// additions result.state_taxes_paid add /additions xdef

additions apportionment.state_additions xdef

// Calculate Georgia state subtractions
0.0 /subtractions xdef

// Subtract Georgia municipal bond interest
// subtractions revenue.ga_municipal_interest add /subtractions xdef

// Subtract Georgia NOL deduction (if different from federal)
// subtractions result.ga_nol_deduction add /subtractions xdef

subtractions apportionment.state_subtractions xdef

"GA income adjustments calculated. Additions: " additions cvs strconcat ", Subtractions: " strconcat subtractions cvs strconcat ". Reference: GA Form 600 Schedule 1, GA Code § 48-7-27" strconcat job.audit_trail swap addto

// Georgia uses 5.75% flat rate
apportionment.state_taxable_income apportionment.state_tax_rate mul /ga_tax xdef

// Subtract Georgia state credits
ga_tax apportionment.state_credits sub 0.0 max /ga_tax xdef
ga_tax apportionment.state_tax xdef

// Calculate refund or amount owed
apportionment.state_payments apportionment.state_tax sub apportionment.state_refund_or_owed xdef

"GA tax calculation: Taxable income: $" apportionment.state_taxable_income cvs strconcat " x 5.75% = $" strconcat ga_tax cvs strconcat ". Credits: $" strconcat apportionment.state_credits cvs strconcat ". Final tax: $" strconcat apportionment.state_tax cvs strconcat ". Reference: GA Form 600, GA Code § 48-7-21" strconcat job.audit_trail swap addto

// No nexus - no filing required
0.0 apportionment.state_tax xdef
apportionment.state_payments apportionment.state_refund_or_owed xdef

// Calculate state additions (customize for Hawaii)
0.0 /additions xdef

// Example: Add back federal interest (not taxable federally but may be taxable to Hawaii)
// additions revenue.federal_bond_interest add /additions xdef

// Example: Add back IRC 199A deduction if state doesn't conform
// additions result.section_199a_deduction add /additions xdef

// Example: Add back bonus depreciation if state decouples
// additions result.bonus_depreciation_total add /additions xdef

additions apportionment.state_additions xdef

// Calculate state subtractions (customize for Hawaii)
0.0 /subtractions xdef

// Example: Subtract municipal bond interest from other states
// subtractions revenue.other_state_municipal_interest add /subtractions xdef

// Example: Subtract state NOL deduction (if different from federal)
// subtractions result.state_nol_deduction add /subtractions xdef

subtractions apportionment.state_subtractions xdef

// Hawaii uses 6.4% flat rate
apportionment.state_taxable_income apportionment.state_tax_rate mul
apportionment.state_tax xdef

// Subtract state credits
apportionment.state_tax apportionment.state_credits sub
0.0 max apportionment.state_tax xdef

// Calculate refund or amount owed
apportionment.state_payments apportionment.state_tax sub
apportionment.state_refund_or_owed xdef

// Physical nexus established - filing required
true result.ia_has_nexus xdef
"Iowa filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.ia_has_nexus xdef
"Iowa filing required: Economic nexus (exceeds $100,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Iowa state additions
0.0 /ia_additions xdef

// Common Iowa additions:
// - State income taxes deducted on federal return
// - Certain expenses related to exempt income
// - Interest expense adjustments (IA does not conform to federal IRC 163(j) limitations)

result.ia_state_taxes_deducted 0.0 ne
{
  ia_additions result.ia_state_taxes_deducted add /ia_additions xdef
} if

ia_additions result.ia_state_additions xdef

// Calculate Iowa state subtractions
0.0 /ia_subtractions xdef

// Common Iowa subtractions:
// - Interest on U.S. government obligations (U.S. Treasury bonds, notes, bills)
// - Interest on IA state and municipal bonds (exempt for IA purposes)
// - IA net operating loss deduction (if applicable)

result.ia_us_interest_income 0.0 ne
{
  ia_subtractions result.ia_us_interest_income add /ia_subtractions xdef
} if

result.ia_municipal_interest 0.0 ne
{
  ia_subtractions result.ia_municipal_interest add /ia_subtractions xdef
} if

ia_subtractions result.ia_state_subtractions xdef

"Iowa additions: $" result.ia_state_additions cvs strconcat ", subtractions: $" strconcat result.ia_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Iowa taxable income // Federal taxable income apportioned to IA + additions - subtractions result.ia_apportioned_income result.ia_state_additions add result.ia_state_subtractions sub 0.0 max result.ia_taxable_income xdef
// Calculate Iowa tax using graduated rates // Bracket 1: 5.5% on first $100,000 result.ia_tax_bracket_threshold result.ia_corp_tax_rate_bracket_1 mul result.ia_tax_bracket_1 xdef
// Bracket 2: 7.1% on amount over $100,000 result.ia_taxable_income result.ia_tax_bracket_threshold sub result.ia_corp_tax_rate_bracket_2 mul result.ia_tax_bracket_2 xdef
// Total tax before credits result.ia_tax_bracket_1 result.ia_tax_bracket_2 add /ia_tax_before_credits xdef
// Subtract Iowa state credits ia_tax_before_credits result.ia_state_credits sub 0.0 max result.ia_tax_liability xdef
// Calculate refund or amount owed result.ia_estimated_payments result.ia_tax_liability sub result.ia_refund_or_owed xdef
"Iowa taxable income: $" result.ia_taxable_income cvs strconcat job.audit_trail swap addto "Iowa tax bracket 1 (5.5% on $100K): $" result.ia_tax_bracket_1 cvs strconcat job.audit_trail swap addto "Iowa tax bracket 2 (7.1% on excess): $" result.ia_tax_bracket_2 cvs strconcat job.audit_trail swap addto "Iowa tax liability: $" result.ia_tax_liability cvs strconcat job.audit_trail swap addto

// Calculate Iowa taxable income result.ia_apportioned_income result.ia_state_additions add result.ia_state_subtractions sub 0.0 max result.ia_taxable_income xdef
// Apply only bracket 1 rate: 5.5% result.ia_taxable_income result.ia_corp_tax_rate_bracket_1 mul result.ia_tax_bracket_1 xdef
0.0 result.ia_tax_bracket_2 xdef
// Subtract Iowa state credits result.ia_tax_bracket_1 result.ia_state_credits sub 0.0 max result.ia_tax_liability xdef
// Calculate refund or amount owed result.ia_estimated_payments result.ia_tax_liability sub result.ia_refund_or_owed xdef
"Iowa taxable income: $" result.ia_taxable_income cvs strconcat job.audit_trail swap addto "Iowa tax liability (5.5%): $" result.ia_tax_liability cvs strconcat job.audit_trail swap addto

