apportionment.state_tax 0.0 xdef
apportionment.state_refund_or_owed apportionment.state_payments xdef

// No nexus - no filing required
apportionment.state_tax 0.0 xdef
apportionment.state_refund_or_owed apportionment.state_payments xdef

// Calculate OR state additions and subtractions
apportionment.state_additions 0.0 xdef
apportionment.state_subtractions 0.0 xdef

// No nexus - no state adjustments
apportionment.state_additions 0.0 xdef
apportionment.state_subtractions 0.0 xdef

// Financial institutions use 7.6% rate
apportionment.state_tax apportionment.state_taxable_income result.or_financial_institution_rate mul xdef
// Minimum tax calculated by separate table
result.or_minimum_tax result.or_minimum_tax xdef
// Tax liability is GREATER of excise tax or minimum tax
apportionment.state_tax apportionment.state_tax result.or_minimum_tax max xdef
// Subtract state credits (but cannot reduce below minimum tax)
apportionment.state_tax apportionment.state_tax apportionment.state_credits sub result.or_minimum_tax max xdef
// Calculate refund or amount owed
apportionment.state_refund_or_owed apportionment.state_payments apportionment.state_tax sub xdef

// Regular corporations use 6.6% flat rate
apportionment.state_tax apportionment.state_taxable_income apportionment.state_tax_rate mul xdef
// Minimum tax calculated by separate table
result.or_minimum_tax result.or_minimum_tax xdef
// Tax liability is GREATER of excise tax or minimum tax
apportionment.state_tax apportionment.state_tax result.or_minimum_tax max xdef
// Subtract state credits (but cannot reduce below minimum tax)
apportionment.state_tax apportionment.state_tax apportionment.state_credits sub result.or_minimum_tax max xdef
// Calculate refund or amount owed
apportionment.state_refund_or_owed apportionment.state_payments apportionment.state_tax sub xdef

// Nexus but no taxable income - minimum tax still applies
// Minimum tax calculated by separate table
apportionment.state_tax result.or_minimum_tax xdef
// Calculate refund or amount owed
apportionment.state_refund_or_owed apportionment.state_payments apportionment.state_tax sub xdef

0.0 /additions xdef


revenue.federal_bond_interest null ne
{
  additions revenue.federal_bond_interest add /additions xdef
} if



result.section_199a_deduction null ne
{
  additions result.section_199a_deduction add /additions xdef
} if



result.state_income_taxes_paid null ne
{
  additions result.state_income_taxes_paid add /additions xdef
} if

additions /apportionment.state_additions xdef


0.0 /subtractions xdef


revenue.tn_municipal_interest null ne
{
  subtractions revenue.tn_municipal_interest add /subtractions xdef
} if


revenue.qualified_subsidiary_dividends null ne
{
  subtractions revenue.qualified_subsidiary_dividends add /subtractions xdef
} if


result.tn_nol_deduction null ne
{
  subtractions result.tn_nol_deduction add /subtractions xdef
} if

subtractions /apportionment.state_subtractions xdef

"TN state-specific income adjustments to federal taxable income. Additions include: Interest on federal obligations (U.S. Treasury bonds, etc.), IRC § 199A qualified business income deduction addback, State franchise and excise taxes paid (not deductible). Subtractions include: Interest on TN state and local bonds, Dividends from 80%+ owned subsidiaries, TN NOL carryforward deduction. Reference: TN Code § 67-4-2006 (Definitions of net earnings), Form FAE 170 Instructions (Schedule J - Adjustments), TN Revenue Ruling 09-13 (IRC conformity)" job.audit_trail swap addto

apportionment.state_taxable_income get /taxable_income xdef
0.0 /calculated_tax xdef
taxable_income get apportionment.vt_bracket_threshold_1 get le
{
  taxable_income get apportionment.vt_tax_rate_tier1 get mul /calculated_tax xdef
}
{
  taxable_income get apportionment.vt_bracket_threshold_2 get le
  {
    apportionment.vt_bracket_threshold_1 get apportionment.vt_tax_rate_tier1 get mul /calculated_tax xdef
    taxable_income get apportionment.vt_bracket_threshold_1 get sub apportionment.vt_tax_rate_tier2 get mul calculated_tax get add /calculated_tax xdef
  }
  {
    apportionment.vt_bracket_threshold_1 get apportionment.vt_tax_rate_tier1 get mul /calculated_tax xdef
    apportionment.vt_bracket_threshold_2 get apportionment.vt_bracket_threshold_1 get sub apportionment.vt_tax_rate_tier2 get mul calculated_tax get add /calculated_tax xdef
    taxable_income get apportionment.vt_bracket_threshold_2 get sub apportionment.vt_tax_rate_tier3 get mul calculated_tax get add /calculated_tax xdef
  } ifelse
} ifelse
calculated_tax get /apportionment.vt_calculated_tax xdef
calculated_tax get apportionment.state_credits get sub 0.0 max /apportionment.state_tax xdef
apportionment.state_payments get apportionment.state_tax get sub /apportionment.state_refund_or_owed xdef
"VT tax calculated using graduated brackets: 6% on first $10K, 7% on $10K-$25K, 8.5% over $25K (one of highest state rates). Reference: 32 V.S.A. 5832" job.audit_trail swap addto
